// Version 2: concatenated standard gzip members containing bounded JSONL
// header/chunk/end frames. No whole-archive JSON string or base64 materialization.
// gzip -dc remains lossless; the versioned verifier checks order, hashes and EOF.
import fs from 'node:fs';import zlib from 'node:zlib';import crypto from 'node:crypto';import assert from 'node:assert/strict';import path from 'node:path';
const CHUNK=1024*1024,FRAME=8*1024*1024;
export function fileDigest(file){const h=crypto.createHash('sha256'),fd=fs.openSync(file,'r'),b=Buffer.alloc(CHUNK);try{for(let n;(n=fs.readSync(fd,b,0,b.length,null))>0;)h.update(b.subarray(0,n));}finally{fs.closeSync(fd);}return h.digest('hex');}
export function writeFramedBundle(file,{generation,nonce,entries},records){const fd=fs.openSync(file,'wx',0o600);const frame=x=>{const body=Buffer.from(JSON.stringify(x)+'\n');assert(body.length<=FRAME,'archive frame bound');const b=zlib.gzipSync(body,{level:9});for(let p=0;p<b.length;)p+=fs.writeSync(fd,b,p,b.length-p);};try{frame({version:2,type:'header',generation,nonce,entries});for(let i=0;i<entries.length;i++){const e=entries[i],input=fs.openSync(path.join(records,e.path),'r'),b=Buffer.alloc(CHUNK);let offset=0;try{do{const n=fs.readSync(input,b,0,Math.min(b.length,e.bytes-offset),null);if(e.bytes>offset&&n===0)throw Error('archive input shortened');frame({type:'chunk',index:i,offset,base64:b.subarray(0,n).toString('base64')});offset+=n;}while(offset<e.bytes);}finally{fs.closeSync(input);}}frame({version:2,type:'end',entries:entries.length});fs.fsyncSync(fd);}finally{fs.closeSync(fd);}}
export function readFramedBundle(file,expected,selected=null){const fd=fs.openSync(file,'r'),size=fs.fstatSync(fd).size;let position=0,header,index=0,offset=0,hash=crypto.createHash('sha256'),ended=false;const pieces=[];
 try{while(position<size){const encoded=Buffer.alloc(Math.min(FRAME,size-position));fs.readSync(fd,encoded,0,encoded.length,position);assert(encoded[0]===31&&encoded[1]===139&&encoded[2]===8&&encoded[3]===0,'invalid framed gzip header');const inflated=zlib.inflateRawSync(encoded.subarray(10),{info:true,maxOutputLength:FRAME});const length=10+inflated.engine.bytesWritten+8;assert(length<=encoded.length,'gzip frame bound');const body=zlib.gunzipSync(encoded.subarray(0,length),{maxOutputLength:FRAME});assert(body.at(-1)===10,'frame terminator');const item=JSON.parse(body);position+=length;
  if(!header){assert(item.version===2&&item.type==='header'&&item.generation===expected.generation&&item.nonce===expected.nonce,'archive ownership/version');assert(JSON.stringify(item.entries)===JSON.stringify(expected.records),'archive manifest mismatch');header=item;continue;}
  if(item.type==='end'){assert(item.version===2&&index===header.entries.length&&offset===0&&item.entries===index&&position===size,'incomplete/trailing archive frames');ended=true;break;}
  assert(item.type==='chunk'&&item.index===index&&item.offset===offset&&index<header.entries.length&&typeof item.base64==='string','archive chunk order');const e=header.entries[index],raw=Buffer.from(item.base64,'base64');assert(raw.toString('base64')===item.base64&&raw.length<=CHUNK&&offset+raw.length<=e.bytes&&(raw.length>0||e.bytes===0),'archive chunk encoding/bound');hash.update(raw);if(e.path===selected)pieces.push(raw);offset+=raw.length;if(offset===e.bytes){assert(hash.digest('hex')===e.sha256,'archive entry corruption');index++;offset=0;hash=crypto.createHash('sha256');}
 }}finally{fs.closeSync(fd);}assert(ended,'missing archive end');if(selected!==null){assert(header.entries.some(e=>e.path===selected),'archive record absent');return Buffer.concat(pieces);}return header.entries;
}
